import { useState } from "react";
import { HiArrowRight, HiBuildingOffice2, HiCheckCircle, HiDevicePhoneMobile, HiEnvelope, HiKey, HiShieldCheck, HiUser } from "react-icons/hi2";
import { useNavigate } from "react-router-dom";
import "./service-access.css";

function ServiceBrand(){return <div className="service-auth-brand"><span><HiShieldCheck/></span><div><strong>OwnTerra</strong><small>Servicio</small></div></div>}

export function ServiceLogin(){
  const navigate=useNavigate();
  const [method,setMethod]=useState("code");
  return <main className="service-auth-page"><section className="service-auth-story"><ServiceBrand/><div><span>Portal para colaboradores externos</span><h1>Tu trabajo.<br/>Sólo lo necesario.</h1><p>Consulta órdenes, agenda visitas, comparte avances y conversa con administración sin entrar al ecosistema completo.</p></div><footer><HiShieldCheck/> Acceso limitado por organización y asignación.</footer></section><section className="service-auth-card"><div className="service-auth-box"><header><span>Acceso externo</span><h2>Inicia sesión</h2><p>Usa el correo o teléfono con el que recibiste tu invitación.</p></header><nav><button className={method==="code"?"active":""} onClick={()=>setMethod("code")}>Código temporal</button><button className={method==="password"?"active":""} onClick={()=>setMethod("password")}>Contraseña</button></nav><form onSubmit={event=>{event.preventDefault();navigate("/portal-servicio")}}><label><span>Correo o teléfono</span><div><HiEnvelope/><input placeholder="correo@proveedor.mx"/></div></label>{method==="password"?<label><span>Contraseña</span><div><HiKey/><input type="password" placeholder="••••••••"/></div></label>:<aside><HiDevicePhoneMobile/><span><strong>Te enviaremos un código de 6 dígitos</strong><small>El código vence en 10 minutos y sólo puede usarse una vez.</small></span></aside>}<button type="submit">{method==="code"?"Enviar código":"Entrar al portal"}<HiArrowRight/></button></form><footer>¿Recibiste una invitación nueva? <button onClick={()=>navigate("/servicio/invitacion")}>Activar acceso</button></footer></div></section></main>;
}

export function ServiceInvitation(){
  const navigate=useNavigate();
  const [type,setType]=useState("company");
  const [step,setStep]=useState(1);
  return <main className="service-invitation-page"><header><ServiceBrand/><span>Invitación protegida · expira en 47:32:18</span></header><section className="service-invitation-card"><div className="invitation-summary"><span>Invitación de Own Terra Demo</span><h1>Únete a su red de servicio.</h1><p>Podrás recibir trabajos y compartir avances sin acceder a información administrativa de la organización.</p><div><HiCheckCircle/><span><strong>Información visible</strong><small>Sólo tus órdenes, ubicaciones asignadas, agenda y conversaciones.</small></span></div><div><HiShieldCheck/><span><strong>Acceso controlado</strong><small>Cada inmueble aparece únicamente durante una asignación activa.</small></span></div></div><div className="invitation-form"><ol><li className={step>=1?"active":""}><span>1</span> Identidad</li><li className={step>=2?"active":""}><span>2</span> Verificación</li><li className={step>=3?"active":""}><span>3</span> Acceso</li></ol>{step===1?<><header><span>Primero, dinos quién resolverá los trabajos</span><h2>Activa tu perfil externo</h2></header><div className="invitation-types"><button className={type==="independent"?"active":""} onClick={()=>setType("independent")}><HiUser/><span><strong>Soy independiente</strong><small>Yo recibo y realizo los servicios.</small></span></button><button className={type==="company"?"active":""} onClick={()=>setType("company")}><HiBuildingOffice2/><span><strong>Represento una empresa</strong><small>Coordino y asigno técnicos.</small></span></button></div><label><span>{type==="company"?"Razón social":"Nombre completo"}</span><input defaultValue={type==="company"?"Climas del Centro":""}/></label>{type==="company"?<label><span>Tu nombre como administrador</span><input defaultValue="Alejandro Morales"/></label>:null}<button className="invitation-next" onClick={()=>setStep(2)}>Continuar a verificación <HiArrowRight/></button></>:step===2?<><header><span>Protegemos la identidad del colaborador</span><h2>Verifica tu teléfono</h2></header><aside className="invitation-code-note"><HiDevicePhoneMobile/><div><strong>Enviamos un código a •••• 9084</strong><small>Escribe los seis dígitos para confirmar que eres el contacto invitado.</small></div></aside><div className="invitation-code">{["4","8","2","1","7","6"].map((value,index)=><input key={index} value={value} readOnly/>)}</div><button className="invitation-next" onClick={()=>setStep(3)}>Verificar código <HiArrowRight/></button></>:<><div className="invitation-success"><HiCheckCircle/><h2>Acceso activado</h2><p>Climas del Centro ya forma parte de la red externa de Own Terra Demo.</p></div><section className="invitation-permissions"><strong>Tu portal incluye</strong><span>Mi Día y agenda</span><span>Órdenes asignadas</span><span>Chat y evidencia</span><span>Equipo técnico de tu empresa</span></section><button className="invitation-next" onClick={()=>navigate("/portal-servicio")}>Abrir Portal de servicio <HiArrowRight/></button></>}</div></section><footer>OwnTerra nunca solicitará información bancaria desde una invitación de acceso.</footer></main>;
}

export function ServiceRegistration(){
  const navigate=useNavigate();
  const [type,setType]=useState("independent");
  const [sent,setSent]=useState(false);
  return <main className="service-registration-page"><header><ServiceBrand/><button type="button" onClick={()=>navigate("/servicio/login")}>Ya tengo cuenta</button></header><section className="service-registration-card"><aside><span>Red de servicio de Own Terra Demo</span><h1>Ofrece tus servicios profesionales.</h1><p>Crea una solicitud para colaborar en mantenimientos y operaciones inmobiliarias. La administración revisará tu perfil antes de habilitar asignaciones.</p><ol><li><strong>1</strong><span>Completa tu perfil y cobertura.</span></li><li><strong>2</strong><span>Own Terra Demo revisa tu solicitud.</span></li><li><strong>3</strong><span>Si es aprobada, activas tu Portal de servicio.</span></li></ol><small>Registrarte no da acceso automático a propiedades ni información privada.</small></aside><div>{!sent?<><header><span>Solicitud de colaboración</span><h2>Cuéntanos quién eres</h2></header><div className="registration-types"><button className={type==="independent"?"active":""} onClick={()=>setType("independent")}><HiUser/><span><strong>Profesional independiente</strong><small>Trabajo por cuenta propia.</small></span></button><button className={type==="company"?"active":""} onClick={()=>setType("company")}><HiBuildingOffice2/><span><strong>Empresa proveedora</strong><small>Tengo coordinadores o técnicos.</small></span></button></div><form onSubmit={event=>{event.preventDefault();setSent(true)}}><label><span>{type==="company"?"Razón social":"Nombre completo"}</span><input required placeholder={type==="company"?"Nombre legal de la empresa":"Tu nombre y apellidos"}/></label>{type==="company"?<label><span>Representante</span><input required placeholder="Nombre del contacto principal"/></label>:null}<label><span>Correo</span><input required type="email" placeholder="contacto@correo.mx"/></label><label><span>WhatsApp</span><input required placeholder="+52 55 0000 0000"/></label><label><span>Especialidad</span><select><option>Plomería</option><option>Electricidad</option><option>Aire acondicionado</option><option>Seguridad</option><option>Limpieza</option><option>Construcción y acabados</option><option>Otra especialidad</option></select></label><label><span>Zona de cobertura</span><input placeholder="Municipios, ciudades o colonias"/></label><label className="wide"><span>Experiencia y servicios</span><textarea rows="3" placeholder="Describe brevemente qué trabajos realizas…"/></label><label className="wide registration-consent"><input type="checkbox" required/><span>Confirmo que la información es correcta y acepto que Own Terra Demo revise mi solicitud.</span></label><button type="submit">Enviar solicitud para revisión <HiArrowRight/></button></form></>:<section className="registration-sent"><HiCheckCircle/><span>Solicitud OT-RS-0084</span><h2>Tu perfil está en revisión.</h2><p>Own Terra Demo recibió tu información. Te avisaremos por correo o WhatsApp cuando exista una decisión.</p><div><small>Estado actual</small><strong>Pendiente de revisión</strong><em>Tiempo estimado: 1–2 días hábiles</em></div><button type="button" onClick={()=>navigate("/servicio/login")}>Ir al inicio de sesión</button></section>}</div></section><footer>Registro administrado por Own Terra Demo · OwnTerra Servicio</footer></main>;
}
